// AFD-291: a flow's run finds the repository's files although its playbook is in
// flows/<key>/generated: a template step's relative source, the root's group_vars, a module in
// library/ with its module_utils/, a filter and a lookup plugin. The flow is generated by the
// engine and run as a run runs it (runProcess), with real Ansible in a WSL distribution; it runs
// only when AFD_TEST_WSL_DISTRO names one with ansible-playbook (Debian on the lab machine).
import { spawn } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterAll, describe, expect, it } from 'vitest';
import { engineFor } from '../../../src/core/engine/engines';
import { parseFlow } from '../../../src/core/flow/document';
import { runProcess } from '../../../src/core/run/command';

const distro = process.env.AFD_TEST_WSL_DISTRO;
const root = mkdtempSync(join(tmpdir(), 'afd-repofiles-'));
afterAll(() => rmSync(root, { recursive: true, force: true }));

const put = (path: string, text: string) => {
  mkdirSync(join(root, path, '..'), { recursive: true });
  writeFileSync(join(root, path), text);
};

function repository(dest: string): void {
  put('templates/motd.j2', 'Hello from {{ inventory_hostname }}\n');
  put('group_vars/all.yml', 'root_group_var: from the root\nboth: root\n');
  put('inv/group_vars/all.yml', 'both: inventory\n');
  put(
    'inv/hosts.ini',
    '[local]\nlocalhost ansible_connection=local ansible_python_interpreter=/usr/bin/python3\n',
  );
  put('module_utils/greet.py', 'def greet(name):\n    return "hi " + name\n');
  put(
    'library/afd_hello.py',
    [
      'from ansible.module_utils.basic import AnsibleModule',
      'from ansible.module_utils.greet import greet',
      'm = AnsibleModule(argument_spec=dict(name=dict(type="str", default="x")))',
      'm.exit_json(changed=False, msg=greet(m.params["name"]))',
      '',
    ].join('\n'),
  );
  put(
    'filter_plugins/shout.py',
    'class FilterModule(object):\n    def filters(self):\n        return {"shout": lambda s: str(s).upper() + "!"}\n',
  );
  put(
    'lookup_plugins/afd_const.py',
    [
      'from ansible.plugins.lookup import LookupBase',
      'class LookupModule(LookupBase):',
      '    def run(self, terms, variables=None, **kw):',
      '        return ["from a lookup"]',
      '',
    ].join('\n'),
  );
  // The hello sample, its three steps bound to what the repository holds.
  const flow = readFileSync(join(__dirname, '../../../samples/hello.flow.yaml'), 'utf8')
    .replace(
      'ref: ansible.builtin.ping',
      `ref: ansible.builtin.template\n    params:\n      src: templates/motd.j2\n      dest: ${dest}`,
    )
    .replace(
      /ref: ansible\.builtin\.setup\n {4}params:\n {6}gather_subset:\n {6}- min/,
      'ref: afd_hello\n    params:\n      name: flow',
    )
    .replace(
      'msg: Hello from {{ inventory_hostname }}',
      `msg: "{{ root_group_var }}|{{ both }}|{{ 'ok' | shout }}|{{ lookup('afd_const') }}"`,
    );
  put('flows/hello/hello.flow.yaml', flow);
  const doc = parseFlow(flow).doc;
  if (!doc) throw new Error('the test flow does not parse');
  for (const f of engineFor(doc).generate(doc, { source: 'hello.flow.yaml' }).files)
    put(`flows/hello/generated/${f.name}`, f.text);
}

describe.skipIf(!distro)('a run finds the repository files (AFD-291, real Ansible in WSL)', () => {
  it('template source, root group_vars over the inventory, library module, filter and lookup', async () => {
    const dest = `/tmp/afd291-${Date.now()}`;
    repository(dest);
    const runDir = join(root, 'run');
    mkdirSync(runDir, { recursive: true });
    writeFileSync(join(runDir, 'vars.json'), JSON.stringify({ devices: ['localhost'] }));
    const spec = runProcess(
      { kind: 'wsl', distro: distro as string, label: 'test' },
      { root, probe: join(__dirname, '../../../probe') },
      {
        playbook: 'flows/hello/generated/hello.yml',
        inventory: 'inv/hosts.ini',
        check: false,
        runDir,
        vault: false,
        hasConfig: false,
        // What the probe's run_config says for a repository without its own ansible.cfg.
        callbacks: { enabled: [], paths: [], plugins: {}, varsEnabled: ['host_group_vars'] },
      },
      'afd291',
    );
    const output = await new Promise<{ code: number | null; text: string }>((resolve) => {
      const child = spawn(spec.command, spec.args, {
        env: { ...process.env, ...spec.env, ANSIBLE_FORCE_COLOR: '0', ANSIBLE_NOCOLOR: '1' },
        cwd: spec.cwd,
        windowsHide: true,
      });
      let text = '';
      child.stdout.on('data', (d) => {
        text += d;
      });
      child.stderr.on('data', (d) => {
        text += d;
      });
      child.on('close', (code) => resolve({ code, text }));
    });
    const plain = output.text
      .replaceAll(`${String.fromCharCode(27)}[`, '[')
      .replace(/\[[0-9;]*m/g, '');
    expect(plain, plain.slice(-3000)).toContain('from the root|root|OK!|from a lookup');
    expect(plain).toMatch(/\[template\] .*\n?.*changed: \[localhost\]|changed: \[localhost\]/);
    expect(plain).not.toMatch(/fatal:|ERROR!|\[ERROR\]/);
    expect(output.code).toBe(0);
  }, 180_000);
});
